head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.gVar = null;



// 이전 케이스에서 열린 창을 닫는다.
scwin.closeOpened = function () {
    try {
        if (scwin.gVar !== null && scwin.gVar.win !== null && scwin.gVar.win.closed === false) scwin.gVar.win.close();
    } catch (e) {}
};



// features 값 조합으로 advancedExcelUpload 실행
//  · Excel 파일 선택 팝업창은 window.open 으로 생성되므로 호출 시점에만 window.open 을 감싸 실제로 전달된 feature 문자열과 창 핸들을 확보한다.
//  · GridView 의 업로드 정보(_excelUploadInfo)는 업로드가 끝나면 초기화되므로 호출 직후 그 자리에서 읽는다.
scwin.runCase = function (strNo, strKind, objOptions) {
    scwin.closeOpened();
    scwin.gVar = { "no" : strNo, "win" : null, "features" : "" };

    scwin.setReturnValue("[" + strNo + "] features " + strKind);

    var fnOpen = window.open;
    window.open = function (sUrl, sName, sFeatures) {
        var objWin = fnOpen.apply(window, arguments);
        if (sName === "fileupWindow") {
            scwin.gVar.win = objWin;
            scwin.gVar.features = (sFeatures === undefined || sFeatures === null) ? "" : String(sFeatures);
        }
        return objWin;
    };
    try {
        grd_upload.advancedExcelUpload(objOptions);
    } finally {
        window.open = fnOpen;
    }

    var strInfo = "";
    try {
        var objInfo = JSON.parse(grd_upload._excelUploadInfo);
        strInfo = (typeof objInfo.sFeatures === "string") ? objInfo.sFeatures : JSON.stringify(objInfo.sFeatures);
    } catch (e) {}

    scwin.setReturnValue("업로드 정보의 sFeatures : " + (strInfo === "" ? "없음" : strInfo));
    scwin.setReturnValue("window.open 전달 문자열 : " + (scwin.gVar.features === "" ? "없음" : scwin.gVar.features));

    setTimeout(function () { scwin.printState(0); }, 1000);
};



// 실제로 열린 창의 속성 출력
//  · 팝업창으로 열리면 브라우저 UI 가 없어 toolbar / menubar 가 표시되지 않고 창 크기도 지정값에 가깝지만 , 탭으로 열리면 브라우저 창 전체 크기가 된다.
scwin.printState = function (nRetry) {
    nRetry = nRetry || 0;

    var objWin = scwin.gVar.win;
    if ((objWin === null || objWin.closed === true) && nRetry < 6) {
        setTimeout(function () { scwin.printState(nRetry + 1); }, 500);
        return;
    }

    if (objWin === null || objWin.closed === true) {
        scwin.setReturnValue("열린 창 : 없음 (창이 확인되지 않음)");
        scwin.setReturnValue("");
        return;
    }

    try {
        scwin.setReturnValue("열린 창 크기 : outerWidth = " + objWin.outerWidth + " , outerHeight = " + objWin.outerHeight + " , screenX = " + objWin.screenX + " , screenY = " + objWin.screenY);
        scwin.setReturnValue("열린 창 속성 : toolbar.visible = " + objWin.toolbar.visible + " , menubar.visible = " + objWin.menubar.visible + " , locationbar.visible = " + objWin.locationbar.visible);
    } catch (e) {
        scwin.setReturnValue("열린 창 : 속성을 읽을 수 없음");
    }
    scwin.setReturnValue("");
};



// ① features 미설정
scwin.btn_case1_onclick = function () {
    scwin.runCase("①", "미설정", {});
};

// ② features 에 left top width height 모두 지정
scwin.btn_case2_onclick = function () {
    scwin.runCase("②", "= \"left=100,top=100,width=700,height=400\"", { "features" : "left=100,top=100,width=700,height=400" });
};

// ③ features 에 left top 만 지정
scwin.btn_case3_onclick = function () {
    scwin.runCase("③", "= \"left=100,top=100\"", { "features" : "left=100,top=100" });
};
